"""L2_0B_verify.py -- reproduces every number in the L2-0B review bundle.  Python 3 + cypari2 (PARI/GP 2.17.2).
Run:  python3 L2_0B_verify.py     (about 8 minutes)

Part 1 (e-descent, L2-09) for C3_p : y^2 = F1(T,W) F2(T,W),  F1 = q_p q_{1/p},  F2 = q_c q_{1/c}.
For a rational point with gcd(T,W)=1, the squarefree class e of F1(T,W) (= class of F2) lies in
  Sel_e = { e > 0 squarefree, supp(e) in S', e in Img_l for all l in S' }
where Img_l CONTAINS { class of F1(t) : t in P^1(Q_l), F1(t)F2(t) in Q_l*^2 }  (superset-safe disc refinement).
If Sel_e = {1} and Jac(y^2 = F_i(x,1)) has rank 0 (ellrank upper bound 0) and |Jac(Q)| = 8 (the number of known
points t = 0, inf, 1, -1 on y^2 = F_i), then every rational point of C3_p has t in {0, inf, 1, -1}.
"""
import cypari2, sys
pari = cypari2.Pari(); pari.allocatemem(2**31, silent=True)

def forms(a, b):
    q = {'p': (b*b, a*a), '1/p': (a*a, b*b), 'c': ((a-b)**2, (a+b)**2), '1/c': ((a+b)**2, (a-b)**2)}
    return q

def evalq(AB, T, W): return AB[0]*T*T + AB[1]*W*W

def F1F2(a, b, T, W):
    q = forms(a, b)
    return evalq(q['p'], T, W)*evalq(q['1/p'], T, W), evalq(q['c'], T, W)*evalq(q['1/c'], T, W)

def val(n, l):
    if n == 0: return 10**9
    k = 0
    while n % l == 0: n //= l; k += 1
    return k

def unit(n, l):
    while n % l == 0: n //= l
    return n

def cls(n, l):
    """class in Q_l*/Q_l*^2 of nonzero integer n"""
    k = val(n, l); u = unit(n, l)
    if l == 2: return (k % 2, u % 8)
    return (k % 2, int(pari.kronecker(u % l, l)))

def is_sq_class(c, l):
    return c[0] == 0 and (c[1] == 1)

def mul_cls(c1, c2, l):
    if l == 2: return ((c1[0]+c2[0]) % 2, (c1[1]*c2[1]) % 8)
    return ((c1[0]+c2[0]) % 2, c1[1]*c2[1])

def local_image(a, b, l, kmax=40):
    """superset of the image of {t in P^1(Q_l): F1F2 square} -> class of F1, by disc refinement.
    chart 0: (T:1), T in Z_l ; chart 1: (1:W), W in l Z_l.
    On a disc z = c0 mod l^k, F(z) = F(c0) mod l^k, so if v(F(c0)) <= k-1 (k-3 for l=2) the class is constant."""
    need = 3 if l == 2 else 1
    img = set()
    unresolved = []
    stack = [(0, r, 1) for r in range(l)] + [(1, 0, 1)]
    while stack:
        ch, c0, k = stack.pop()
        T, W = (c0, 1) if ch == 0 else (1, c0)
        f1, f2 = F1F2(a, b, T, W)
        v1, v2 = val(f1, l), val(f2, l)
        if v1 <= k - need and v2 <= k - need:
            # both classes constant on the disc (exact)
            c1, c2 = cls(f1, l), cls(f2, l)
            if is_sq_class(mul_cls(c1, c2, l), l):
                img.add(c1)
            continue
        if v2 <= k - need:
            # F2 class constant on the disc; the square condition forces class(F1) = class(F2): superset-safe
            img.add(cls(f2, l)); continue
        if v1 <= k - need:
            img.add(cls(f1, l)); continue
        if k >= kmax:
            unresolved.append((ch, c0, k, v1, v2)); continue
        for r in range(l):
            stack.append((ch, c0 + r*l**k, k+1))
    return img, unresolved

def S_prime(a, b):
    """2 and the primes dividing A_i D_j - B_i C_j for the six pairs of quadratic forms"""
    q = forms(a, b); ks = list(q); S = {2}
    for i in range(4):
        for j in range(i+1, 4):
            A, B = q[ks[i]]; C, D = q[ks[j]]
            n = abs(A*D - B*C)
            if n > 1: S |= set(int(x) for x in pari.factor(n)[0])
    return sorted(S)

def sel_e(a, b, kmax=40):
    S = S_prime(a, b)
    imgs = {}; problems = []
    for l in S:
        img, unres = local_image(a, b, l, kmax)
        imgs[l] = img
        if unres: problems.append((l, len(unres)))
    sel = []
    from itertools import combinations
    for r in range(len(S)+1):
        for sub in combinations(S, r):
            e = 1
            for x in sub: e *= x
            if all(cls(e, l) in imgs[l] for l in S): sel.append(e)
    return S, imgs, sel, problems

def jac_check(a, b, which):
    """y^2 = F_which(x,1); returns (rank bounds from ellrank, |E(Q)_tors|) of its Jacobian"""
    q = forms(a, b)
    if which == 1: A, B = q['p'], q['1/p']
    else: A, B = q['c'], q['1/c']
    pol = pari(f'({A[0]}*x^2+{A[1]})*({B[0]}*x^2+{B[1]})')
    E = pari.ellinit(pari.ellfromeqn(pari('y^2') - pol))
    r = pari.ellrank(E)
    return (int(r[0]), int(r[1])), int(pari.elltors(E)[0])

def decide(a, b, kmax=40):
    S, imgs, sel, problems = sel_e(a, b, kmax)
    res = {'p': f'{a}/{b}', 'S': S, 'sel': sel, 'problems': problems}
    if problems or sel != [1]:
        res['verdict'] = 'OPEN (Sel_e != {1} or unresolved discs)'
        return res
    for which in (2, 1):
        rk, nt = jac_check(a, b, which)
        res[f'J{which}'] = (rk, nt)
        if rk == (0, 0) and nt == 8:
            res['verdict'] = f'EXCLUDED via F{which}: only t in {{0,inf,1,-1}}'
            return res
    res['verdict'] = 'OPEN (no rank-0 factor)'
    return res

# ===================== reproduction of the bundle =====================
import random, json, time
from math import gcd
from collections import Counter
GP = r"""
ehomo(e1,e2,e3) = ellinit([0,-(e1+e2+e3),0,e1*e2+e1*e3+e2*e3,-e1*e2*e3]);
Erho(a,b) = my(k=4*a*b*(a^2-b^2)); ehomo(k,-k,-(a^2+b^2)^2);
Etau(a,b) = my(n=a^2-b^2,m=a*b); ehomo(8*n^2*m^2,-8*n^2*m^2,-(n^4+16*m^4));
oddp(x) = my(y=abs(x)); y/2^valuation(y,2);
om(x) = omega(oddp(x));
n1mod8(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%8==1);
c1(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%4==1);
c3(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%4==3);
eps(a,b) = my(m=a*b); if(m%4==2, 1, if(m%2==1 && (m%8==3 || m%8==5), 1, -1));
eps1(a,b) = if((a*b)%4==2, 1, -1);
eps2(a,b) = my(m=a*b); if(m%2==1 && (m%8==3 || m%8==5), 1, -1);
thm(a,b) = my(P=a^2+2*a*b-b^2, Q=a^2-2*a*b-b^2, N1=om(a*b*(a^2-b^2))+n1mod8(P*Q)); [-eps(a,b)*(-1)^N1, (-1)^(N1+om(a^2+b^2))];
J1(a,b) = my(u=2*a*b, v=a^2-b^2); ellinit([0, v^2-u^2, 0, -u^2*v^2, 0]);
J2(a,b) = my(u=2*a*b, v=a^2-b^2); ellinit([0, u^2-v^2, 0, -u^2*v^2, 0]);
JF1(a,b) = ellinit(ellfromeqn(y^2-(b^2*x^2+a^2)*(a^2*x^2+b^2)));
JF2(a,b) = ellinit(ellfromeqn(y^2-((a-b)^2*x^2+(a+b)^2)*((a+b)^2*x^2+(a-b)^2)));
wJ1(a,b) = -eps1(a,b)*(-1)^(om(a*b) + om(a^2+b^2) + c1(a^2-b^2));
wJ2(a,b) = -eps2(a,b)*(-1)^(om(a^2-b^2) + om(a^2+b^2) + c1(a*b));
"""
for line in GP.strip().split("\n"):
    pari(line)
def W(f, a, b): return int(pari(f'{f}({a},{b})'))
t0 = time.time()
# ---- A. three examples
for a, b in [(10,1),(23,1),(11,6)]:
    r = decide(a, b); print("A", f"{a}/{b}", r['sel'], r.get('J2'), r.get('J1'), r['verdict'])
# ---- B. all coprime 1<=b<a<30
rows = []
for a in range(2, 30):
    for b in range(1, a):
        if gcd(a, b) != 1: continue
        r = decide(a, b); wr, wt = [int(x) for x in pari(f'thm({a},{b})')]
        rows.append((a, b, wr, wt, r['verdict'].startswith('EXCL'), r['sel']))
tot = len(rows); ex = sum(r[4] for r in rows)
bm = [r for r in rows if r[2] == -1 and r[3] == -1]
print("B all p a<30:", tot, "excluded by e-descent:", ex, "| both -1 locus:", len(bm), "excluded:", sum(r[4] for r in bm))
# ---- C. combine with rank-0 criteria (E_rho rank 0 & torsion 4, or E_tau rank 0 & torsion Z/2xZ/4)
still = []
for a, b, wr, wt, exc, sel in rows:
    if exc: continue
    Er, Et = pari(f'Erho({a},{b})'), pari(f'Etau({a},{b})')
    ok_r = int(pari.ellrank(Er)[1]) == 0 and int(pari.elltors(Er)[0]) == 4
    ok_t = int(pari.ellrank(Et)[1]) == 0 and [int(x) for x in pari.elltors(Et)[1]] == [4, 2]
    if not (ok_r or ok_t): still.append((a, b))
print("C open after e-descent:", tot-ex, " -> also not settled by rank-0 criteria:", len(still))
# ---- D. local-image validation (seed 9)
random.seed(9); n = bad = 0
for a, b in [(10,1),(23,1),(11,6),(11,8),(14,13),(7,2),(19,4)]:
    for l in S_prime(a, b):
        img, unres = local_image(a, b, l)
        M = l**4 if l < 20 else l**2
        for _ in range(3000):
            T = random.randrange(M); Wv = random.choice([1, l*random.randrange(1, M)])
            f1, f2 = F1F2(a, b, T, Wv)
            if f1 == 0 or f2 == 0: continue
            c1_, c2_ = cls(f1, l), cls(f2, l)
            if is_sq_class(mul_cls(c1_, c2_, l), l):
                n += 1
                if c1_ not in img: bad += 1
print("D sampled local points with F1F2 square:", n, " missing from computed image:", bad)
# ---- E. J1, J2 models and root numbers
bi = sum(1 for a in range(2,30) for b in range(1,a) if gcd(a,b)==1 and
         (pari(f'ellisisom(J1({a},{b}),JF1({a},{b}))')==0 or pari(f'ellisisom(J2({a},{b}),JF2({a},{b}))')==0))
print("E1 J1~Jac(y^2=F1), J2~Jac(y^2=F2), a<30: failures", bi)
n = bad = 0
for a in range(-40, 41):
    for b in range(-40, 41):
        if a*b == 0 or abs(a) == abs(b) or gcd(a, b) != 1: continue
        n += 1
        if int(pari.ellrootno(pari(f'J1({a},{b})'))) != W('wJ1',a,b) or int(pari.ellrootno(pari(f'J2({a},{b})'))) != W('wJ2',a,b): bad += 1
print("E2 closed formulas for w(J1), w(J2), signed |a|,|b|<=40:", n, "failures", bad)
n = bad = 0
for a in range(2, 70):
    for b in range(1, a):
        if gcd(a, b) != 1: continue
        for J, e in (('J1','eps1'),('J2','eps2')):
            n += 1
            if int(pari.ellrootno(pari(f'{J}({a},{b})'), 2)) != W(e, a, b): bad += 1
print("E3 2-adic factors w2(J1)=eps1, w2(J2)=eps2, a<70:", n, "failures", bad)
bad = sum(1 for a in range(2,120) for b in range(1,a) if gcd(a,b)==1 and
          W('wJ1',a,b)*W('wJ2',a,b) != int(pari(f'-eps({a},{b})*(-1)^c3({a}*{b}*({a}^2-{b}^2))')))
print("E4 product formula w(J1)w(J2), a<120: failures", bad)
# ---- F. e-descent outcome vs (w(J1), w(J2)), a<30
c = Counter()
for a, b, wr, wt, exc, sel in rows:
    st = 'EXCL' if exc else ('OPEN-sel' if sel != [1] else 'OPEN-rank')
    c[(st, W('wJ1',a,b), W('wJ2',a,b))] += 1
print("F", sorted(c.items()))
# ---- G. densities
for N in (50, 100, 150):
    cc = Counter(); tot2 = 0
    for a in range(2, N):
        for b in range(1, a):
            if gcd(a, b) != 1: continue
            tot2 += 1
            wr, wt = [int(x) for x in pari(f'thm({a},{b})')]; w1, w2 = W('wJ1',a,b), W('wJ2',a,b)
            cc['rho_tau'] += (wr == wt == -1); cc['J'] += (w1 == w2 == -1); cc['H'] += (wr == wt == w1 == w2 == -1)
    print("G", N, tot2, dict(cc))
print("total time", round(time.time()-t0), "s")

# Expected output (PARI/GP 2.17.2):
# A 10/1 [1] ((0, 0), 8) None EXCLUDED via F2: only t in {0,inf,1,-1}
# A 23/1 [1] ((0, 0), 8) None EXCLUDED via F2: only t in {0,inf,1,-1}
# A 11/6 [1] ((1, 1), 8) ((0, 0), 8) EXCLUDED via F1: only t in {0,inf,1,-1}
# B all p a<30: 269 excluded by e-descent: 183 | both -1 locus: 66 excluded: 57
# C open after e-descent: 86  -> also not settled by rank-0 criteria: 46
# D sampled local points with F1F2 square: 146806  missing from computed image: 0
# E1 J1~Jac(y^2=F1), J2~Jac(y^2=F2), a<30: failures 0
# E2 closed formulas for w(J1), w(J2), signed |a|,|b|<=40: 3912 failures 0
# E3 2-adic factors w2(J1)=eps1, w2(J2)=eps2, a<70: 2938 failures 0
# E4 product formula w(J1)w(J2), a<120: failures 0
# F [(('EXCL', -1, 1), 58), (('EXCL', 1, -1), 61), (('EXCL', 1, 1), 64), (('OPEN-rank', -1, -1), 48), (('OPEN-rank', -1, 1), 17), (('OPEN-rank', 1, -1), 9), (('OPEN-sel', -1, -1), 8), (('OPEN-sel', -1, 1), 2), (('OPEN-sel', 1, -1), 2)]
# G 50 753 {'rho_tau': 197, 'J': 175, 'H': 30}
# G 100 3003 {'rho_tau': 782, 'J': 743, 'H': 188}
# G 150 6817 {'rho_tau': 1713, 'J': 1703, 'H': 443}

\\ L2_verify_v2.gp -- PARI/GP 2.15+ : Stage38 L2 の root number 定理の全検査（再現用）
\\ 使い方: gp -q -s 1G  の中で  read("L2_verify_v2.gp")
\\ 乱数は setrand で固定。各テストの最後に件数と不一致数を表示する。
ehomo(e1,e2,e3) = ellinit([0,-(e1+e2+e3),0,e1*e2+e1*e3+e2*e3,-e1*e2*e3]);
Erho(a,b) = my(k=4*a*b*(a^2-b^2)); ehomo(k,-k,-(a^2+b^2)^2);
Etau(a,b) = my(n=a^2-b^2,m=a*b); ehomo(8*n^2*m^2,-8*n^2*m^2,-(n^4+16*m^4));
oddp(x) = my(y=abs(x)); y/2^valuation(y,2);
om(x) = omega(oddp(x));
n1mod8(x) = my(f=factor(oddp(x))[,1]); sum(i=1,#f, f[i]%8==1);
eps(a,b) = my(m=a*b); if(m%4==2, 1, if(m%2==1 && (m%8==3 || m%8==5), 1, -1));
thm(a,b) = {
  my(P=a^2+2*a*b-b^2, Q=a^2-2*a*b-b^2, s=a^2+b^2, N1);
  N1 = om(a*b*(a^2-b^2)) + n1mod8(P*Q);
  [-eps(a,b)*(-1)^N1, (-1)^(N1+om(s))];
}
w2thm(a,b) = [eps(a,b), -1];   \\ 2進因子の主張: w2(E_rho)=eps, w2(E_tau)=-1
pari(a,b) = my(Er=Erho(a,b), Et=Etau(a,b)); [[ellrootno(Er),ellrootno(Et)], [ellrootno(Er,2),ellrootno(Et,2)]];
ok(a,b) = my(r=pari(a,b)); r[1]==thm(a,b) && r[2]==w2thm(a,b);
lemA(t) = ellrootno(ellinit([0,1-t,0,-t,0]),2);

